'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc,formText,type HotelWorkspace} from '@/lib/pilot';
import {useClientReady} from '@/lib/client-ready';
import {definitiveBookingRejection} from '@/lib/pending-booking';
import {folioMoney,balanceBasis} from '@/lib/folio-reports';
import {reservationStatus} from '@/lib/reservation-status';
import {noShowKey,validNoShow,validateNoShowPreview,validateNoShowReceipt,noShowBlockers,type NoShowCommand,type NoShowResult,type NoShowStatus,type NoShowPreview} from '@/lib/no-shows';
type Scope={actor:string;tenant:string;property:string;reservation:string};
type PanelProps=Scope&{onBusyChange:(busy:boolean)=>void;onSaved:()=>Promise<void>;onReviewFolio:()=>void;onReviewServiceDays:()=>void};
export function NoShowAction(props:Scope&{canReview:boolean;disabled:boolean;onOpen:()=>void}){return useClientReady()?<Action key={noShowKey(props.actor,props.tenant,props.property,props.reservation)} {...props}/>:null}
function Action({actor,tenant,property,reservation,canReview,disabled,onOpen}:Scope&{canReview:boolean;disabled:boolean;onOpen:()=>void}){const [pending]=useState(()=>{try{return sessionStorage.getItem(noShowKey(actor,tenant,property,reservation))!==null}catch{return true}});return canReview||pending?<button className="secondary" disabled={disabled} onClick={onOpen}>{pending?'Recover no-show request':'Review no-show'}</button>:null}
export function NoShowPanel(props:PanelProps){return useClientReady()?<NoShowForm key={noShowKey(props.actor,props.tenant,props.property,props.reservation)} {...props}/>:<p>Loading no-show recovery…</p>}
function NoShowForm({actor,tenant,property,reservation,onBusyChange,onSaved,onReviewFolio,onReviewServiceDays}:PanelProps){
 const key=noShowKey(actor,tenant,property,reservation);const [initial]=useState(()=>{try{const raw=sessionStorage.getItem(key);if(raw===null)return {pending:null,error:''};const p:unknown=JSON.parse(raw);if(!validNoShow(p,reservation))throw Error();return {pending:p,error:''}}catch{return {pending:null,error:'The saved no-show request cannot be read. Reconcile its status before preparing another request.'}}});
 const [pending,setPending]=useState<NoShowCommand|null>(initial.pending),[preview,setPreview]=useState<NoShowPreview|null>(null),[role,setRole]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(initial.error),[notice,setNotice]=useState(''),[readError,setReadError]=useState('');const alive=useRef(true),sequence=useRef(0),lock=useRef(false),callback=useRef(onBusyChange);
 useEffect(()=>{callback.current=onBusyChange},[onBusyChange]);
 async function read(){return Promise.all([hotelRpc<NoShowPreview>('no_show_preview',{p_tenant:tenant,p_property:property,p_reservation:reservation}),hotelRpc<HotelWorkspace>('workspace',{p_tenant:tenant,p_property:property})])}
 const readTimer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
 async function refresh(){
  const seq=++sequence.current;clearTimeout(readTimer.current);setPreview(null);setRole('');setReadError('');
  let timer:ReturnType<typeof setTimeout>|undefined;
  try{const [p,w]=await Promise.race([read(),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Loading the no-show review took too long. Check your connection and refresh the review.')),15000);readTimer.current=timer;})]);if(alive.current&&sequence.current===seq){if(w.property?.id!==property||!['owner','manager','staff'].includes(w.role))throw Error('Current staff access to this property could not be verified.');setPreview(validateNoShowPreview(p,reservation));setRole(w.role)}}
  catch(e){if(alive.current&&sequence.current===seq)setReadError(e instanceof Error?e.message:'Unable to load no-show review.')}
  finally{clearTimeout(timer);}
 }
 useEffect(()=>{alive.current=true;void refresh();return()=>{alive.current=false;sequence.current++;clearTimeout(readTimer.current);if(lock.current)callback.current(false)}},[tenant,property,reservation]);
 async function task(work:()=>Promise<void>){if(lock.current||initial.error)return;lock.current=true;setBusy(true);callback.current(true);setError('');setNotice('');try{await work()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to confirm no-show status.')}finally{lock.current=false;if(alive.current){setBusy(false);callback.current(false)}}}
 async function accepted(status:NoShowStatus,p:NoShowCommand){validateNoShowReceipt(status,p);if(!alive.current)return;sequence.current++;clearTimeout(readTimer.current);sessionStorage.removeItem(key);setPending(null);setPreview(null);setNotice('No-show disposition confirmed. Review folio charges and service allocations separately.');await onSaved()}
 async function check(){if(!pending)return;await task(async()=>{const status=await hotelRpc<NoShowStatus>('no_show_request_status',{p_tenant:tenant,p_property:property,p_request:pending.p_request});if(status.found)await accepted(status,pending);else if(alive.current)setNotice('No receipt was found. The earlier request may still complete. Keep this exact request and check again or retry it when authorized.')})}
 async function mark(p:NoShowCommand){const recovering=pending!==null;await task(async()=>{if(!validNoShow(p,reservation))throw Error('Review the reservation version, property date and reason before marking.');sessionStorage.setItem(key,JSON.stringify(p));setPending(p);let result:NoShowResult;
  try{result=await hotelRpc<NoShowResult>('mark_no_show',{p_tenant:tenant,p_property:property,...p})}catch(e){if(definitiveBookingRejection(e)){const status=await hotelRpc<NoShowStatus>('no_show_request_status',{p_tenant:tenant,p_property:property,p_request:p.p_request});if(status.found){await accepted(status,p);return}if(alive.current){if(!recovering){sessionStorage.removeItem(key);setPending(null);await refresh()}else setNotice('The earlier request remains unresolved. Check its receipt before preparing another no-show request.')}throw e}throw Error('The no-show result is uncertain. Check its saved receipt or retry this exact request.')}
  await accepted({found:true,action:'mark_no_show',result},p);
 })}
 const manager=['owner','manager'].includes(role),amount=(value:number|null)=>value==null?'Unknown':folioMoney(value);
 return <><p>Record an unstarted direct or imported stay as a no-show once its scheduled departure date has arrived. This is a terminal cancellation disposition; a later arrival requires a new capacity-checked reservation.</p><button className="secondary" disabled={busy} onClick={()=>void refresh()}>Refresh no-show review</button>{(error||readError)&&<div className="pilot-error" role="alert">{error||readError}</div>}{notice&&<output className="pilot-notice">{notice}</output>}{preview&&<section className="pilot-no-show-review"><h3>Current reservation review</h3><p>{reservationStatus(preview)} · {preview.arrival??'Unknown arrival'} to {preview.departure??'Unknown departure'}</p><p>Property date: {preview.business_date}. {preview.late_arrival_policy}</p><p>Amount basis: {balanceBasis(preview.opening_mode)}</p><dl><div><dt>Charges</dt><dd>{amount(preview.charges_minor)}</dd></div><div><dt>Net externally recorded payments</dt><dd>{amount(preview.recorded_paid_minor)}</dd></div><div><dt>Balance</dt><dd>{amount(preview.balance_minor)}</dd></div></dl><p className="pilot-service-blockers">{preview.financial_review_required?'Financial review is required. ':''}{preview.service_warning}</p><p>Marking does not add fees, waive charges, refund payments, or close a service day.</p><div className="pilot-actions"><button className="secondary" disabled={busy} onClick={onReviewFolio}>Review reservation folio</button><button className="secondary" disabled={busy} onClick={onReviewServiceDays}>Review service-day allocations</button></div>{preview.blockers.length>0&&<ul>{preview.blockers.map(b=><li key={b}>{noShowBlockers[b]??b}</li>)}</ul>}</section>}{pending?<div className="pilot-notice"><h3>Recover the saved no-show request</h3><p>Reservation {pending.p_reservation} · reviewed date {pending.p_expected_business_date}</p><p>{pending.p_reason}</p><button className="secondary" disabled={busy} onClick={()=>void check()}>Check saved no-show request</button>{manager&&<button className="primary" disabled={busy} onClick={()=>void mark(pending)}>Retry exact no-show request</button>}{!manager&&<p>A manager can retry. Your current property access can check the original receipt.</p>}</div>:!preview?<p>Load the latest reservation review before marking.</p>:!manager?<p>Only an owner or manager can mark a new no-show.</p>:preview.eligible&&<form key={preview.source_version+'/'+preview.business_date+'/'+preview.generated_at} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget),p:NoShowCommand={p_request:crypto.randomUUID(),p_reservation:reservation,p_expected_source_version:preview.source_version,p_expected_business_date:preview.business_date,p_reason:formText(f,'reason').trim()};if(!validNoShow(p,reservation)){setError('Enter a review reason of 4–500 characters on one line.');return}void mark(p)}}><label className="field">No-show review reason<input name="reason" required minLength={4} maxLength={500} disabled={busy||!!initial.error}/></label><label className="pilot-check"><input type="checkbox" required disabled={busy||!!initial.error}/>I confirmed the guest never started this stay and reviewed the separate financial and allocation decisions.</label><button className="primary" disabled={busy||!!initial.error}>Mark as no show</button></form>}</>;
}
